import java.io.*; import javax.imageio.*; import java.awt.image.*; import java.awt.Color; public class test_crop { public static void main(String[] args) throws Exception { File f = new File("test_event_105.img"); BufferedImage img = ImageIO.read(f); if (img == null) { System.out.println("null img"); return; } int cropHeight = (int) (img.getHeight() * 0.70); BufferedImage cropped = img.getSubimage(0, 0, img.getWidth(), cropHeight); BufferedImage newImage = new BufferedImage(cropped.getWidth(), cropped.getHeight(), BufferedImage.TYPE_INT_RGB); newImage.createGraphics().drawImage(cropped, 0, 0, Color.WHITE, null); ByteArrayOutputStream baos = new ByteArrayOutputStream(); ImageIO.write(newImage, "jpg", baos); System.out.println("JPEG size: " + baos.size()); } }
